Add-Type -AssemblyName System.Drawing

function Measure-Spread($path, $label) {
  $img = [System.Drawing.Bitmap]::FromFile($path)
  $w = $img.Width
  $h = $img.Height
  $midY = [int]($h/2)

  # sample background color from far corner
  $bg = $img.GetPixel(5,5)

  function ColorDist($c1, $c2) {
    $dr = [int]$c1.R - [int]$c2.R
    $dg = [int]$c1.G - [int]$c2.G
    $db = [int]$c1.B - [int]$c2.B
    return [math]::Sqrt($dr*$dr + $dg*$dg + $db*$db)
  }

  # scan left to right at midY to find left/right edges of the spread (page vs bg)
  $threshold = 12
  $leftEdge = -1
  $rightEdge = -1
  for ($x = 0; $x -lt $w; $x++) {
    $p = $img.GetPixel($x, $midY)
    if ((ColorDist $p $bg) -gt $threshold) { $leftEdge = $x; break }
  }
  for ($x = $w-1; $x -ge 0; $x--) {
    $p = $img.GetPixel($x, $midY)
    if ((ColorDist $p $bg) -gt $threshold) { $rightEdge = $x; break }
  }

  # scan top to bottom at the horizontal center of the spread to find top/bottom page edges
  $midX = [int](($leftEdge + $rightEdge)/2)
  $topEdge = -1
  $bottomEdge = -1
  for ($y = 0; $y -lt $h; $y++) {
    $p = $img.GetPixel($midX, $y)
    if ((ColorDist $p $bg) -gt $threshold) { $topEdge = $y; break }
  }
  for ($y = $h-1; $y -ge 0; $y--) {
    $p = $img.GetPixel($midX, $y)
    if ((ColorDist $p $bg) -gt $threshold) { $bottomEdge = $y; break }
  }

  $canvasCenter = $w / 2.0
  $spreadCenter = ($leftEdge + $rightEdge) / 2.0
  $bookHeight = $bottomEdge - $topEdge
  $bookHeightFrac = $bookHeight / $h

  "=== $label ===" 
  "size: ${w}x${h}"
  "bg sample: {0},{1},{2}" -f $bg.R,$bg.G,$bg.B
  "left edge: $leftEdge   right edge: $rightEdge   spread width: $($rightEdge-$leftEdge)"
  "top edge: $topEdge   bottom edge: $bottomEdge   book height: $bookHeight ($([math]::Round($bookHeightFrac*100,1))% of canvas height)"
  "canvas centre x: $canvasCenter   spread centre x: $spreadCenter   offset: $([math]::Round($spreadCenter-$canvasCenter,1))px"
  ""
  $img.Dispose()
}

